  }
}

export class Chat extends Agent {
  async onMessage(connection, message) {
    const [cmd, jobId, ...rest] = String(message).split(' ');
    if (cmd === 'try') {
      const sandbox = await this.dynamicAgents.get(Sandbox, jobId);
      connection.send(await sandbox.evaluate(rest.join(' ')));
    } else if (cmd === 'cancel') {
      this.dynamicAgents.abort(Sandbox, jobId, new Error('cancelled'));
      connection.send(`cancelled ${jobId}`);
    }
  }
}

